static float N(float x,float z,float scale)=>Mathf.PerlinNoise(x/scale+31,z/scale+59);
public static float LakeR(float x,float z){float u=(x-Cx)/Rx,v=(z-Cz)/Rz,a=Mathf.Atan2(v,u);return Mathf.Sqrt(u*u+v*v)/(1+.065f*Mathf.Sin(a*3+.5f)+.04f*Mathf.Sin(a*7-1)+.018f*Mathf.Sin(a*11));}
static float Hill(float x,float z,float cx,float cz,float rx,float rz,float a){float u=(x-cx)/rx,v=(z-cz)/rz;return a*Mathf.Exp(-(u*u+v*v)*1.6f);}
public static float Height(float x,float z){float rolling=8.2f+Hill(x,z,38,75,89,90,3.2f)+Hill(x,z,197,209,95,92,4.4f)+Hill(x,z,59,222,80,90,2.2f)+1.15f*Mathf.Sin(x*.032f+.3f)*Mathf.Cos(z*.026f)+1.4f*(N(x,z,57)-.5f);float r=LakeR(x,z);if(r<1)return Water-2.15f*(1-r*r);return Mathf.Lerp(Water,rolling,Mathf.SmoothStep(0,1,Mathf.InverseLerp(1,1.42f,r)));}
static Vector3 Normal(float x,float z)=>new Vector3((Height(x-1,z)-Height(x+1,z))*.5f,1,(Height(x,z-1)-Height(x,z+1))*.5f).normalized;
static float PathX(float z){float q=(z-Cz)/47;return 112+18*Mathf.Sin(z*.026f)+.12f*(z-128)-22*Mathf.Exp(-q*q*q*q);}
static T Save<T>(T item,string path) where T:UnityEngine.Object{var old=AssetDatabase.LoadMainAssetAtPath(path);if(old){EditorUtility.CopySerialized(item,old);UnityEngine.Object.DestroyImmediate(item);return (T)old;}AssetDatabase.CreateAsset(item,path);return item;}
static Texture2D Mask(string name,Color[] values){var t=new Texture2D(512,512,TextureFormat.RGB24,false,true);t.SetPixels(values);t.Apply();var path=Root+name+".png";File.WriteAllBytes(path,t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);AssetDatabase.ImportAsset(path);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.sRGBTexture=false;imp.wrapMode=TextureWrapMode.Clamp;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
