public static void Run(){Directory.CreateDirectory(Root);var scene=EditorSceneManager.OpenScene(Source+"TerrainLookZoom1.unity",OpenSceneMode.Single);var terrain=UnityEngine.Object.FindFirstObjectByType<Terrain>(FindObjectsInactive.Include);var data=UnityEngine.Object.Instantiate(terrain.terrainData);data.name="Gentle rolling meadow with shallow pond basin";data.size=new Vector3(256,40,256);int n=data.heightmapResolution;var heights=new float[n,n];float min=100,max=0;for(int z=0;z<n;z++)for(int x=0;x<n;x++){float h=Height(x*256f/(n-1),z*256f/(n-1));heights[z,x]=h/40;min=Mathf.Min(min,h);max=Mathf.Max(max,h);}data.SetHeights(0,0,heights);data=Save(data,Root+"RollingPondTerrain.asset");terrain.terrainData=data;terrain.enabled=false;terrain.GetComponent<TerrainCollider>().terrainData=data;
var ground=scene.GetRootGameObjects().First(g=>g.name.StartsWith("Ground with meadow"));var mesh=UnityEngine.Object.Instantiate(ground.GetComponent<MeshFilter>().sharedMesh);var verts=mesh.vertices;for(int i=0;i<verts.Length;i++){var p=verts[i];p.y=Height(p.x,p.z);verts[i]=p;}mesh.vertices=verts;mesh.RecalculateNormals();mesh.RecalculateBounds();ground.GetComponent<MeshFilter>().sharedMesh=Save(mesh,Root+"RollingGround.asset");
int removed=0;foreach(var root in scene.GetRootGameObjects().Where(g=>g.name.StartsWith("MapMagic generated")))foreach(Transform obj in root.transform.Cast<Transform>().ToArray()){var p=obj.position;bool adult=!obj.name.StartsWith("Stone")&&!obj.name.StartsWith("Shrub")&&obj.localScale.x>.4f;float cutoff=adult?1.14f:1.06f;if(LakeR(p.x,p.z)<cutoff){UnityEngine.Object.DestroyImmediate(obj.gameObject);removed++;continue;}p.y=terrain.SampleHeight(p);obj.position=p;}
var trees=scene.GetRootGameObjects().First(g=>g.name.StartsWith("MapMagic generated woodland")).transform;
var canopy=new float[512*512];foreach(Transform tree in trees){if(tree.name.StartsWith("Stone")||tree.localScale.x<.4f)continue;var b=tree.GetComponentInChildren<Renderer>().bounds;float radius=Mathf.Max(b.extents.x,b.extents.z)*1.1f+2;for(int z=Mathf.Max(0,(int)((tree.position.z-radius)*2));z<=Mathf.Min(511,(int)((tree.position.z+radius)*2));z++)for(int x=Mathf.Max(0,(int)((tree.position.x-radius)*2));x<=Mathf.Min(511,(int)((tree.position.x+radius)*2));x++){float d=Vector2.Distance(new Vector2(x*.5f,z*.5f),new Vector2(tree.position.x,tree.position.z));canopy[z*512+x]=Mathf.Max(canopy[z*512+x],1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(radius*.3f,radius,d)));}}
var coverage=new Color[512*512];var variation=new Color[512*512];var shore=new Color[512*512];var waterDepth=new Color[512*512];for(int z=0;z<512;z++)for(int x=0;x<512;x++){int i=z*512+x;float wx=x*.5f,wz=z*.5f,r=LakeR(wx,wz),h=Height(wx,wz),depth=Mathf.Max(0,Water-h),distance=(r-1)*34;float d=Mathf.Abs(wx-PathX(wz))+(N(wx,wz,3)-.5f)*.8f;float land=Mathf.SmoothStep(0,1,Mathf.InverseLerp(1.03f,1.15f,r));float path=(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(1,2.8f,d)))*land;float shoulder=(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(2.3f,4.7f,d)))*(.4f+.6f*N(wx,wz,7))*land;float wood=Mathf.Clamp01(canopy[i]+(N(wx,wz,6)-.5f)*.18f)*land;coverage[i]=new Color(wood,path,shoulder,1);
float damp=(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.3f,3.7f,Mathf.Abs(distance))))*(.7f+.3f*N(wx,wz,3));float gravel=(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(1.8f,5.7f,Mathf.Abs(distance))))*(.3f+.6f*N(wx,wz,5));shore[i]=new Color(damp,gravel,depth>0?1:0,1);float dry=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.43f,.7f,N(wx+52,wz-31,33)))*.4f*(1-wood)*Mathf.SmoothStep(0,1,Mathf.InverseLerp(1.2f,1.65f,r));variation[i]=new Color(dry,wood*(1-wood)*N(wx,wz,5)*.2f,0,1);waterDepth[i]=new Color(depth/3,0,0,1);}
var material=new Material(ground.GetComponent<Renderer>().sharedMaterial);material.shader=Shader.Find("CityForge/Rolling Pond Ground");material.SetTexture("_Coverage",Mask("GroundCoverage",coverage));material.SetTexture("_Variation",Mask("GroundVariation",variation));material.SetTexture("_Shore",Mask("ShoreCoverage",shore));material=Save(material,Root+"Ground.mat");ground.GetComponent<Renderer>().sharedMaterial=material;BuildGrass(scene,coverage,shore,material);
var surface=new GameObject("Quiet pond with shallow water and live reflections");surface.layer=4;var wm=new Mesh();wm.vertices=new[]{new Vector3(75,Water,80),new Vector3(75,Water,177),new Vector3(192,Water,80),new Vector3(192,Water,177)};wm.triangles=new[]{0,1,2,2,1,3};wm.RecalculateNormals();wm.RecalculateBounds();surface.AddComponent<MeshFilter>().sharedMesh=Save(wm,Root+"WaterSurface.asset");var waterMat=new Material(Shader.Find("CityForge/Quiet Pond Water"));waterMat.SetTexture("_DepthMask",Mask("PondDepth",waterDepth));waterMat=Save(waterMat,Root+"Water.mat");var wr=surface.AddComponent<MeshRenderer>();wr.sharedMaterial=waterMat;wr.shadowCastingMode=ShadowCastingMode.Off;
int reeds=ShoreObjects(scene,terrain);
camera=UnityEngine.Object.FindFirstObjectByType<Camera>();var rig=camera.GetComponent<CityForgeCameraController>();rig.FrameArea(2048,120,new Vector3(128,0,128));typeof(CityForgeCameraController).GetField("focus",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(rig,new Vector3(128,8,128));rig.SetZoomLevel(1);rig.ApplyPose();camera.farClipPlane=5000;
reflections=surface.AddComponent<PondPlanarReflection>();reflections.sourceCamera=camera;reflections.waterHeight=Water;reflections.waterMaterial=waterMat;reflections.RenderNow();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,Root+"RollingPondZoom1.unity");captureAt=EditorApplication.timeSinceStartup+4;
