static void BuildGrass(UnityEngine.SceneManagement.Scene scene,Color[] coverage,Color[] shore,Material ground){var v=new List<Vector3>();var normals=new List<Vector3>();var tri=new List<int>();var rnd=new System.Random(46023);for(int i=0;i<65000;i++){float x=5+(float)rnd.NextDouble()*246,z=5+(float)rnd.NextDouble()*246;int index=Mathf.Clamp((int)(z*2),0,511)*512+Mathf.Clamp((int)(x*2),0,511);if(coverage[index].r>.35f||coverage[index].g>.05f||shore[index].r>.42f||LakeR(x,z)<1.08f||N(x,z,5)<.43f)continue;var b=new Vector3(x,Height(x,z),z);for(int j=0;j<3;j++){float a=(float)rnd.NextDouble()*6.283f;var side=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a))*.065f;int q=v.Count;v.Add(b-side);v.Add(b+side);v.Add(b+Vector3.up*(.1f+(float)rnd.NextDouble()*.15f)+side*.5f);normals.Add(Vector3.up);normals.Add(Vector3.up);normals.Add(Vector3.up);tri.AddRange(new[]{q,q+1,q+2});}}var mesh=new Mesh{indexFormat=IndexFormat.UInt32};mesh.SetVertices(v);mesh.SetNormals(normals);mesh.SetTriangles(tri,0);mesh.RecalculateBounds();var grass=scene.GetRootGameObjects().First(g=>g.name.StartsWith("Short meadow grass"));grass.GetComponent<MeshFilter>().sharedMesh=Save(mesh,Root+"MeadowGrass.asset");var mat=new Material(ground);mat.SetFloat("_SurfaceScale",.92f);grass.GetComponent<Renderer>().sharedMaterial=Save(mat,Root+"Grass.mat");}
static GameObject ReedPrefab(){var vertices=new List<Vector3>();var green=new List<int>();var brown=new List<int>();var rnd=new System.Random(17534);
Action<Vector3,Vector3,float,List<int>> ribbon=(a,b,width,indices)=>{var side=Vector3.Cross(b-a,new Vector3(.2f,.05f,1)).normalized*width;int q=vertices.Count;vertices.Add(a-side);vertices.Add(a+side);vertices.Add(b-side*.45f);vertices.Add(b+side*.45f);indices.AddRange(new[]{q,q+2,q+1,q+1,q+2,q+3});};
for(int i=0;i<14;i++){float a=(float)rnd.NextDouble()*6.283f,r=.8f*Mathf.Sqrt((float)rnd.NextDouble()),height=1.25f+(float)rnd.NextDouble()*.85f;var b=new Vector3(Mathf.Cos(a)*r,0,Mathf.Sin(a)*r);ribbon(b,b+Vector3.up*height,.013f,green);for(int j=0;j<3;j++){float angle=a+j*2.2f;var direction=new Vector3(Mathf.Cos(angle),0,Mathf.Sin(angle));var start=b+Vector3.up*(.2f+j*.15f);var mid=start+direction*.28f+Vector3.up*.55f;var tip=start+direction*.6f+Vector3.up*.7f;ribbon(start,mid,.06f,green);ribbon(mid,tip,.037f,green);}ribbon(b+Vector3.up*(height-.2f),b+Vector3.up*(height+.12f),.052f,brown);}
var mesh=new Mesh();mesh.SetVertices(vertices);mesh.subMeshCount=2;mesh.SetTriangles(green,0);mesh.SetTriangles(brown,1);mesh.RecalculateNormals();mesh.RecalculateBounds();mesh=Save(mesh,Root+"ReedClump.asset");Material Make(string name,Color c){var mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.SetColor("_BaseColor",c);mat.SetFloat("_Smoothness",.08f);mat.SetFloat("_Cull",0);return Save(mat,Root+name+".mat");}var go=new GameObject("Pond reeds and cattails");go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterials=new[]{Make("ReedGreen",new Color(.22f,.30f,.11f)),Make("ReedHeads",new Color(.19f,.11f,.055f))};var prefab=PrefabUtility.SaveAsPrefabAsset(go,Root+"ReedClump.prefab");UnityEngine.Object.DestroyImmediate(go);return prefab;}
static MatrixAsset Map(string name,Func<float,float,float> value){var map=ScriptableObject.CreateInstance<MatrixAsset>();map.source=MatrixAsset.Source.New;map.matrix=new Matrix(new CoordRect(0,0,256,256));for(int z=0;z<256;z++)for(int x=0;x<256;x++)map.matrix.arr[z*256+x]=value(x*256f/255,z*256f/255);return Save(map,Root+name+".asset");}
static T Add<T>(Graph graph,T gen,float x,float y) where T:Generator{gen.id=Den.Tools.Id.Generate();if(gen is IMultiInlet multi)foreach(IUnit inlet in multi.Inlets()){inlet.SetGen(gen);inlet.Id=Den.Tools.Id.Generate();}gen.guiPosition=new Vector2(x,y);graph.Add(gen);return gen;}
static void Branch(Graph graph,MatrixAsset map,GameObject[] prefabs,float density,Vector2 scale,int seed,float y){var import=Add(graph,new Import200{matrixAsset=map},0,y);var scatter=Add(graph,new Scatter200{density=density,uniformity=.12f,relax=.25f,seed=seed},210,y);var mask=Add(graph,new MapMagic.Nodes.ObjectsGenerators.Mask200{seed=seed+1},420,y);graph.Link(import,mask.maskIn);graph.Link(scatter,mask.srcIn);var adjust=Add(graph,new Adjust200{useRandom=true,scale=scale,rotation=new Vector2(0,360),seed=seed+2},630,y);graph.Link(mask,adjust.input);var output=Add(graph,new ObjectsOutput{prefabs=prefabs,seed=seed+3,posSettings=new PositioningSettings{relativeHeight=true,objHeight=false,useRotation=true,rotateYonly=true,useScale=true}},840,y);graph.Link(adjust,output);}
static int ShoreObjects(UnityEngine.SceneManagement.Scene scene,Terrain terrain){var reeds=ReedPrefab();var reedsMap=Map("ReedSuitability",(x,z)=>{float d=(LakeR(x,z)-1)*34;float shore=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.5f,3.2f,Mathf.Abs(d)));return shore*Mathf.SmoothStep(0,1,Mathf.InverseLerp(.36f,.66f,N(x+47,z+13,8)))*(Height(x,z)>Water-.55f?1:0);});var stoneMap=Map("BankStoneSuitability",(x,z)=>{float d=(LakeR(x,z)-1)*34;return (1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.5f,3.7f,Mathf.Abs(d-3.5f))))*(.2f+.8f*N(x,z,7));});var heightMap=Map("RollingPondHeight",(x,z)=>Height(x,z)/40);
var graph=ScriptableObject.CreateInstance<Graph>();graph.random=new Noise(730421,32768);var heights=Add(graph,new Import200{matrixAsset=heightMap},0,-250);var heightOut=Add(graph,new HeightOutput200(),230,-250);graph.Link(heights,heightOut);Branch(graph,reedsMap,new[]{reeds},150000,new Vector2(.65f,1.25f),61945,0);Branch(graph,stoneMap,Enumerable.Range(1,3).Select(i=>AssetDatabase.LoadAssetAtPath<GameObject>("Assets/CityForge/Art/Environment/ObjectsWoodlandStudy/Stone"+i+".prefab")).ToArray(),33000,new Vector2(.32f,.9f),94516,370);graph=Save(graph,Root+"RollingPondGraph.asset");AssetDatabase.SaveAssets();var data=new MapMagic.Products.TileData{area=new Area(new Vector2D(0,0),new Vector2D(256,256),256,0),globals=new Globals{height=40},random=graph.random};data.heights=new MatrixWorld(data.area.full.rect,data.area.full.worldPos,data.area.full.worldSize,40);for(int z=0;z<256;z++)for(int x=0;x<256;x++)data.heights.arr[z*256+x]=Height(x*256f/255,z*256f/255)/40;var stop=new StopToken();graph.Prepare(data,terrain);graph.Generate(data,stop);graph.Finalize(data,stop);var applied=data.ApplyOfType<ObjectsOutput.ApplyObjectsData>();if(applied==null)throw new Exception("Missing pond shoreline output");var root=new GameObject("MapMagic pond shoreline reeds and stones");var stoneMaterial=AssetDatabase.LoadAssetAtPath<Material>(Source+"Stone.mat");int count=0;foreach(var pair in applied.prototypes.Select((p,i)=>(p,i)))foreach(var tr in applied.transitions[pair.i]){var go=(GameObject)PrefabUtility.InstantiatePrefab(pair.p.prefab,scene);go.transform.SetParent(root.transform,false);go.transform.position=new Vector3(tr.pos.x,terrain.SampleHeight(tr.pos),tr.pos.z);go.transform.rotation=tr.rotation;go.transform.localScale=tr.scale;if(pair.p.prefab==reeds)count++;else foreach(var r in go.GetComponentsInChildren<Renderer>())r.sharedMaterials=r.sharedMaterials.Select(m=>stoneMaterial).ToArray();}return count;}
static void Capture(string name){reflections.RenderNow();var rt=new RenderTexture(3840,2160,24);rt.Create();var previous=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(camera,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var tex=new Texture2D(3840,2160,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,3840,2160),0,0);tex.Apply();File.WriteAllBytes(Output+name+".png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{RenderTexture.active=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
